(async () => {
  const H = {'X-Gigg-CSRF': '1'};
  const J = {'Content-Type': 'application/json', 'X-Gigg-CSRF': '1'};
  const g = await (await fetch('/api/v1/projects/1/gigs', {method: 'POST', headers: J, body: JSON.stringify({title: 'Harbor redesign: review the new layout', priority: 2, description_md: 'First pass.'})})).json();
  const pic = (w, h, a, b, text) => new Promise((ok) => {
    const c = document.createElement('canvas'); c.width = w; c.height = h;
    const x = c.getContext('2d');
    const gr = x.createLinearGradient(0, 0, w, h); gr.addColorStop(0, a); gr.addColorStop(1, b);
    x.fillStyle = gr; x.fillRect(0, 0, w, h);
    x.fillStyle = 'rgba(255,255,255,0.18)';
    for (let i = 0; i < 9; i++) { x.beginPath(); x.arc((i * 137) % w, (i * 211) % h, 40 + i * 14, 0, 7); x.fill(); }
    x.fillStyle = '#fff'; x.font = 'bold ' + Math.round(h / 9) + 'px sans-serif'; x.fillText(text, w * 0.08, h * 0.88);
    c.toBlob(ok, 'image/png');
  });
  // a short WAV tone, written by hand
  const wav = (() => {
    const n = 8000, b = new DataView(new ArrayBuffer(44 + n * 2));
    const s = (o, t) => [...t].forEach((ch, i) => b.setUint8(o + i, ch.charCodeAt(0)));
    s(0, 'RIFF'); b.setUint32(4, 36 + n * 2, true); s(8, 'WAVEfmt '); b.setUint32(16, 16, true); b.setUint16(20, 1, true); b.setUint16(22, 1, true);
    b.setUint32(24, 8000, true); b.setUint32(28, 16000, true); b.setUint16(32, 2, true); b.setUint16(34, 16, true); s(36, 'data'); b.setUint32(40, n * 2, true);
    for (let i = 0; i < n; i++) b.setInt16(44 + i * 2, Math.sin(i / 3) * 8000, true);
    return new Blob([b.buffer]);
  })();
  // a one-second WebM recorded from a canvas
  const webm = await new Promise((ok) => {
    try {
      const c = document.createElement('canvas'); c.width = 320; c.height = 180;
      const x = c.getContext('2d'); let f = 0;
      const t = setInterval(() => { x.fillStyle = 'hsl(' + (f++ * 12) + ',70%,50%)'; x.fillRect(0, 0, 320, 180); x.fillStyle = '#fff'; x.font = 'bold 28px sans-serif'; x.fillText('Walkthrough', 60, 100); }, 40);
      const r = new MediaRecorder(c.captureStream(25), {mimeType: 'video/webm'}); const parts = [];
      r.ondataavailable = (e) => parts.push(e.data); r.onstop = () => { clearInterval(t); ok(new Blob(parts)); };
      r.start(); setTimeout(() => r.stop(), 1200);
    } catch (e) { ok(null); }
  });
  const up = async (name, body) => await (await fetch('/api/v1/gigs/' + g.id + '/attachments?' + new URLSearchParams({filename: name}), {method: 'POST', headers: {...H, 'Content-Type': 'application/octet-stream'}, body})).json();
  const layout = await up('new-layout.png', await pic(1400, 800, '#3E63DD', '#8E4EC6', 'New layout'));
  const phone = await up('phone.png', await pic(700, 1100, '#12A594', '#3E63DD', 'Phone'));
  const log = await up('review.log', new Blob(['2026-11-21 review started\n2026-11-21 3 issues found\n']));
  const tone = await up('chime.wav', wav);
  const clip = webm ? await up('walkthrough.webm', webm) : null;
  const desc = 'The new layout for **Harbor**, as agreed on Thursday:\n\n![new-layout.png](/api/v1/attachments/' + layout.id + '/file)\n\nThe full review is in [review.log](/api/v1/attachments/' + log.id + '/file).';
  const p = await fetch('/api/v1/gigs/' + g.id, {method: 'PATCH', headers: J, body: JSON.stringify({description_md: desc})});
  const c = await fetch('/api/v1/gigs/' + g.id + '/comments', {method: 'POST', headers: J, body: JSON.stringify({body_md: 'On a phone the header wraps, see:\n\n![](/api/v1/attachments/' + phone.id + '/thumb)\n\nI think the menu should collapse.'})});
  return [g.id, layout.mime, phone.mime, log.mime, tone.mime + ' ' + tone.inline, clip ? clip.mime + ' ' + clip.inline : 'no webm', p.status, c.status];
})()

(async () => {
  const c = document.createElement('canvas'); c.width = 600; c.height = 340; const x = c.getContext('2d');
  x.fillStyle = '#E5484D'; x.fillRect(0, 0, 600, 340); x.fillStyle = '#fff'; x.font = 'bold 40px sans-serif'; x.fillText('Pasted shot', 40, 300);
  const blob = await new Promise((ok) => c.toBlob(ok, 'image/png'));
  const t = document.querySelector('form[aria-label="Edit gig"] textarea'); t.focus(); t.setSelectionRange(t.value.length, t.value.length);
  const dt = new DataTransfer(); dt.items.add(new File([blob], 'shot.png', {type: 'image/png'}));
  t.dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt, bubbles: true, cancelable: true}));
  return t.value.includes('![Uploading shot.png…]()') || t.value.includes('![shot.png](');
})()

(() => {
  const box = document.querySelector('.add-comment .mde');
  const dt = new DataTransfer(); dt.items.add(new File(['meeting notes\n'], 'notes.txt', {type: 'text/plain'}));
  box.dispatchEvent(new DragEvent('dragover', {dataTransfer: dt, bubbles: true, cancelable: true}));
  box.dispatchEvent(new DragEvent('drop', {dataTransfer: dt, bubbles: true, cancelable: true}));
  return !document.querySelector('aside.panel').classList.contains('att-drop');
})()

